		baseConn = n.Config.Managed.Connection.Config
	case n.RemovedConfig != nil && n.RemovedConfig.Managed != nil && n.RemovedConfig.Managed.Connection != nil:
		baseConn = n.RemovedConfig.Managed.Connection.Config
