		// Get the configuration.
		config := t.Config.Descendent(addr.Module)

		if config == nil {
			log.Printf("[TRACE] AttachResourceConfigTransformer: %q (%T) has no configuration available", dag.VertexName(v), v)
		} else if r := config.Module.ResourceByAddr(addr.Resource); r != nil {
			log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) config from %#v", dag.VertexName(v), v, r.DeclRange)
			arn.AttachResourceConfig(r, nil)
			if t.hasConfigConditions(addr.Module, addr.Resource) {
				log.Printf("[TRACE] AttachResourceConfigTransformer: %q has configuration conditions", dag.VertexName(v))
			}
			if gnapmc, ok := v.(GraphNodeAttachProviderMetaConfigs); ok {
				log.Printf("[TRACE] AttachResourceConfigTransformer: attaching provider meta configs to %s", dag.VertexName(v))
				if config.Module.ProviderMetas != nil {
					gnapmc.AttachProviderMetaConfigs(config.Module.ProviderMetas)
				} else {
					log.Printf("[TRACE] AttachResourceConfigTransformer: no provider meta configs available to attach to %s", dag.VertexName(v))
				}
			}
		}

		// A removed block is interpreted relative to the module it is declared
		// in, so it might target a resource in one of that module's descendants.
		// We therefore need to search the modules containing this resource's
		// address, not only the module where the resource itself was declared.
		// This also allows us to find a removed block for a module that no
		// longer exists in configuration at all.
		if r := t.findRemovedBlock(addr); r != nil {
			log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) removed block from %#v", dag.VertexName(v), v, r.DeclRange)

			// Validation ensures that there can't be both a resource/data block
			// and a removed block referring to the same configuration, so
			// we can assume that this isn't clobbering a non-removed resource
			// configuration we already attached above.
			arn.AttachResourceConfig(nil, r)
		}
	}

	return nil
}

// findRemovedBlock returns the "removed" block, if any, that targets the given
// resource address. Removed blocks are relative to the module they are declared
// in, so we search the modules along the path to the target resource, from the
// root down. This matches the precedence used when collecting remove
// statements, where a removed block in an ancestor module overrides one in a
// descendent module.
func (t *AttachResourceConfigTransformer) findRemovedBlock(addr addrs.ConfigResource) *configs.Removed {
	if t.Config == nil || t.Config.Module == nil {
		return nil
	}

	cfg := t.Config
	for cfg != nil && cfg.Module != nil && len(cfg.Path) <= len(addr.Module) {
		for _, r := range cfg.Module.Removed {
			if r.From == nil {
				continue
			}
			crAddr, ok := r.From.RelSubject.(addrs.ConfigResource)
			if !ok || crAddr.Resource != addr.Resource {
				// Not for this resource at all, so can't possibly match.
				continue
			}

			// The removed block's target is relative to the module where the
			// block was declared, so it only matches if the module prefixes
			// line up.
			if len(cfg.Path)+len(crAddr.Module) != len(addr.Module) {
				continue
			}
			matches := true
			for i, name := range crAddr.Module {
				if addr.Module[len(cfg.Path)+i] != name {
					matches = false
					break
				}
			}
			if matches {
				return r
			}
		}

		if len(cfg.Path) == len(addr.Module) {
			break
		}
		cfg = cfg.Children[addr.Module[len(cfg.Path)]]
	}

	return nil
}

